package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

@Service @Transactional
public class FinanceLedgerGovernance {
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext database;private final AccessPolicy access;private final FinanceAccountingService accounting;
 public FinanceLedgerGovernance(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext database,AccessPolicy access,FinanceAccountingService accounting){this.jdbc=jdbc;this.database=database;this.access=access;this.accounting=accounting;}
 private TenantPrincipal prepare(){access.requirePermission("finance.configure");var p=access.principal();database.apply(p.tenantId());return p;}
 private Map<String,Object> book(TenantPrincipal p,UUID id){var r=jdbc.queryForList("select * from fa_book where tenant_id=:tenant and id=:id",base(p).addValue("id",id));if(r.isEmpty())throw missing();access.requireOrgScope(id(r.getFirst().get("hotel_id")));return r.getFirst();}
 public Map<String,Object> list(UUID bookId){var p=prepare();book(p,bookId);return Map.of("items",value(jdbc.queryForList("select * from fc_ledger_change where tenant_id=:tenant and book_id=:book order by created_at desc,id",base(p).addValue("book",bookId))));}
 public Map<String,Object> account(UUID request,FinanceAccountingModels.Account input,String reason){return propose(request,"ACCOUNT",input.bookId(),map(json(input)),reason);}
 public Map<String,Object> rule(UUID request,FinanceAccountingModels.Rule input,String reason){return propose(request,"RULE",input.bookId(),map(json(input)),reason);}
 private Map<String,Object> propose(UUID request,String kind,UUID book,Map<String,Object> payload,String reason){var p=prepare();var b=book(p,book);if(reason==null||reason.isBlank()||reason.length()>2000)throw bad("请填写科目/映射修订依据");String hash=FinanceService.hash(json(new TreeMap<>(payload))+":"+kind+":"+reason);var q=base(p).addValue("id",request);jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,94))",Map.of("key",p.tenantId()+":ledger-draft:"+request),Object.class);var old=jdbc.queryForList("select * from fc_ledger_change where tenant_id=:tenant and id=:id",q);if(!old.isEmpty()){if(!hash.equals(old.getFirst().get("request_hash"))||!p.actorId().equals(old.getFirst().get("created_by")))throw conflict("修订编号已用于不同资料");return output(old.getFirst());}
  jdbc.update("insert into fc_ledger_change(id,tenant_id,book_id,kind,payload,request_hash,reason,created_by) values(:id,:tenant,:book,:kind,cast(:payload as jsonb),:hash,:reason,:actor)",q.addValue("book",book).addValue("kind",kind).addValue("payload",json(payload)).addValue("hash",hash).addValue("reason",reason));new FinanceControlGuard(jdbc).event(p,id(b.get("hotel_id")),"LEDGER_CHANGE",request,"PROPOSED",Map.of("kind",kind,"payload",payload,"reason",reason));return output(jdbc.queryForMap("select * from fc_ledger_change where tenant_id=:tenant and id=:id",q));}
 public Map<String,Object> publish(UUID id,FinanceControlModels.Version in,boolean reject){var p=prepare();var q=base(p).addValue("id",id);var rows=jdbc.queryForList("select * from fc_ledger_change where tenant_id=:tenant and id=:id for update",q);if(rows.isEmpty())throw missing();var r=rows.getFirst();var book=book(p,id(r.get("book_id")));version(r,in.expectedVersion());if(!"DRAFT".equals(r.get("status"))||p.actorId().equals(r.get("created_by")))throw conflict("由独立配置复核人处理未发布修订");if(!reject){jdbc.queryForObject("select set_config('app.finance_ledger_publication',:id,true)",Map.of("id",id.toString()),String.class);try{if("ACCOUNT".equals(r.get("kind")))accounting.saveAccount(JSON.convertValue(map(r.get("payload")),FinanceAccountingModels.Account.class));else accounting.saveRule(JSON.convertValue(map(r.get("payload")),FinanceAccountingModels.Rule.class));}finally{jdbc.queryForObject("select set_config('app.finance_ledger_publication','',true)",Map.of(),String.class);}}
  jdbc.update("update fc_ledger_change set status=:status,published_by=:actor,version=version+1 where tenant_id=:tenant and id=:id",q.addValue("status",reject?"REJECTED":"PUBLISHED"));new FinanceControlGuard(jdbc).event(p,id(book.get("hotel_id")),"LEDGER_CHANGE",id,reject?"REJECTED":"PUBLISHED",Map.of("payload",map(r.get("payload")),"note",in.note()));return output(jdbc.queryForMap("select * from fc_ledger_change where tenant_id=:tenant and id=:id",q));}
 static void requirePublication(NamedParameterJdbcTemplate jdbc,TenantPrincipal p,String kind,Object payload){if(!new FinanceControlGuard(jdbc).installed())return;String token=jdbc.queryForObject("select current_setting('app.finance_ledger_publication',true)",Map.of(),String.class);if(token==null||token.isBlank())throw conflict("请先保存科目/映射修订草稿，由另一名有配置权限的财务人员发布");var rows=jdbc.queryForList("select * from fc_ledger_change where tenant_id=:tenant and id=:id and kind=:kind and status='DRAFT'",base(p).addValue("id",UUID.fromString(token)).addValue("kind",kind));if(rows.isEmpty()||p.actorId().equals(rows.getFirst().get("created_by"))||!map(json(payload)).equals(map(rows.getFirst().get("payload"))))throw conflict("发布凭据与本次科目/映射修订不符");}
}
